CREATE TABLE IF NOT EXISTS "customers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account reference quoted on every manifest and invoice.
	"account_number" VARCHAR(24) NOT NULL UNIQUE,
	-- Shipper name. Individuals are stored here too, under their own name.
	"company_name" VARCHAR(200) NOT NULL,
	-- Address for manifests, exception notices and invoices.
	"contact_email" VARCHAR(320) NOT NULL,
	-- Number used when a pickup or a customs document goes wrong.
	"contact_phone" VARCHAR(32),
	-- Billing city, kept for tax jurisdiction rather than for delivery.
	"billing_city" VARCHAR(120),
	-- ISO 3166-1 alpha-2 code, which decides the tax and customs regime for the account.
	"billing_country_code" CHAR(2) NOT NULL,
	-- Invoice payment window. Zero means prepay, which changes whether a label can even be printed.
	"credit_terms_days" SMALLINT NOT NULL DEFAULT 30,
	-- False stops new shipments without touching the historical ones.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- Account opening time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "customers" IS 'The shipper who holds the account, which is almost never the person waiting for the parcel. Recipients are deliberately not accounts here: they are snapshotted onto the shipment instead.';
COMMENT ON COLUMN "customers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "customers"."account_number" IS 'Account reference quoted on every manifest and invoice.';
COMMENT ON COLUMN "customers"."company_name" IS 'Shipper name. Individuals are stored here too, under their own name.';
COMMENT ON COLUMN "customers"."contact_email" IS 'Address for manifests, exception notices and invoices.';
COMMENT ON COLUMN "customers"."contact_phone" IS 'Number used when a pickup or a customs document goes wrong.';
COMMENT ON COLUMN "customers"."billing_city" IS 'Billing city, kept for tax jurisdiction rather than for delivery.';
COMMENT ON COLUMN "customers"."billing_country_code" IS 'ISO 3166-1 alpha-2 code, which decides the tax and customs regime for the account.';
COMMENT ON COLUMN "customers"."credit_terms_days" IS 'Invoice payment window. Zero means prepay, which changes whether a label can even be printed.';
COMMENT ON COLUMN "customers"."is_active" IS 'False stops new shipments without touching the historical ones.';
COMMENT ON COLUMN "customers"."created_at" IS 'Account opening time.';

CREATE TABLE IF NOT EXISTS "service_levels" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Short code printed on the label, e.g. NDA or GROUND.
	"code" VARCHAR(16) NOT NULL UNIQUE,
	-- Customer-facing name, e.g. Next Day Air.
	"name" VARCHAR(80) NOT NULL,
	-- Committed business days in transit, used to compute the promised date at label creation.
	"transit_days" SMALLINT NOT NULL DEFAULT 3,
	-- Local time on the delivery date the service is guaranteed by. Null for services with no time commitment, which is a different thing from midnight.
	"guaranteed_by_time" TIME,
	-- Whether a proof of delivery signature is mandatory. Drives what a courier is allowed to do at the door.
	"signature_required" BOOLEAN NOT NULL DEFAULT false,
	-- Liability included in minor units before any declared-value surcharge.
	"includes_insurance_minor" INTEGER NOT NULL DEFAULT 0,
	-- International services add customs steps to the route plan and to the scan sequence.
	"is_international" BOOLEAN NOT NULL DEFAULT false,
	-- False withdraws the product from sale while in-flight shipments keep their commitments.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "service_levels" IS 'The product being sold. The commitment lives here so that the promised date on a shipment can be computed once and then frozen, even after the product itself is repriced or retimed.';
COMMENT ON COLUMN "service_levels"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "service_levels"."code" IS 'Short code printed on the label, e.g. NDA or GROUND.';
COMMENT ON COLUMN "service_levels"."name" IS 'Customer-facing name, e.g. Next Day Air.';
COMMENT ON COLUMN "service_levels"."transit_days" IS 'Committed business days in transit, used to compute the promised date at label creation.';
COMMENT ON COLUMN "service_levels"."guaranteed_by_time" IS 'Local time on the delivery date the service is guaranteed by. Null for services with no time commitment, which is a different thing from midnight.';
COMMENT ON COLUMN "service_levels"."signature_required" IS 'Whether a proof of delivery signature is mandatory. Drives what a courier is allowed to do at the door.';
COMMENT ON COLUMN "service_levels"."includes_insurance_minor" IS 'Liability included in minor units before any declared-value surcharge.';
COMMENT ON COLUMN "service_levels"."is_international" IS 'International services add customs steps to the route plan and to the scan sequence.';
COMMENT ON COLUMN "service_levels"."is_active" IS 'False withdraws the product from sale while in-flight shipments keep their commitments.';

CREATE TABLE IF NOT EXISTS "hubs" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Facility code used on every scan and manifest, e.g. LON-SC1.
	"code" VARCHAR(12) NOT NULL UNIQUE,
	-- Facility name.
	"name" VARCHAR(160) NOT NULL,
	-- sort_centre | depot | delivery_station | gateway | customs | locker. A gateway is where a shipment enters or leaves a country.
	"kind" VARCHAR(24) NOT NULL DEFAULT 'sort_centre',
	-- Street address of the facility.
	"address_line1" VARCHAR(200) NOT NULL,
	-- City the facility serves.
	"city" VARCHAR(120) NOT NULL,
	-- ISO 3166-1 alpha-2 country code.
	"country_code" CHAR(2) NOT NULL,
	-- IANA zone. Cut-off times are local, and a parcel that misses a 19:00 cut-off misses it in local time.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Position, used for the tracking map and for distance estimates.
	"latitude" NUMERIC(9,6),
	-- Position, used for the tracking map and for distance estimates.
	"longitude" NUMERIC(9,6),
	-- Local time after which a parcel waits for the next outbound wave.
	"sort_cutoff" TIME,
	-- False closes a facility without invalidating decades of scans taken there.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "hubs" IS 'A physical facility. Every scan happens somewhere, and that somewhere is one of these rows, which is what turns a stream of events into a path through a network.';
COMMENT ON COLUMN "hubs"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "hubs"."code" IS 'Facility code used on every scan and manifest, e.g. LON-SC1.';
COMMENT ON COLUMN "hubs"."name" IS 'Facility name.';
COMMENT ON COLUMN "hubs"."kind" IS 'sort_centre | depot | delivery_station | gateway | customs | locker. A gateway is where a shipment enters or leaves a country.';
COMMENT ON COLUMN "hubs"."address_line1" IS 'Street address of the facility.';
COMMENT ON COLUMN "hubs"."city" IS 'City the facility serves.';
COMMENT ON COLUMN "hubs"."country_code" IS 'ISO 3166-1 alpha-2 country code.';
COMMENT ON COLUMN "hubs"."timezone" IS 'IANA zone. Cut-off times are local, and a parcel that misses a 19:00 cut-off misses it in local time.';
COMMENT ON COLUMN "hubs"."latitude" IS 'Position, used for the tracking map and for distance estimates.';
COMMENT ON COLUMN "hubs"."longitude" IS 'Position, used for the tracking map and for distance estimates.';
COMMENT ON COLUMN "hubs"."sort_cutoff" IS 'Local time after which a parcel waits for the next outbound wave.';
COMMENT ON COLUMN "hubs"."is_active" IS 'False closes a facility without invalidating decades of scans taken there.';

CREATE INDEX "idx_hubs_city_country"
ON "hubs" ("city", "country_code");
CREATE INDEX "idx_hubs_kind_active"
ON "hubs" ("kind", "is_active");

CREATE TABLE IF NOT EXISTS "routes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Lane identifier, e.g. LON-MAN-N1. Operations plan and staff by this code.
	"code" VARCHAR(24) NOT NULL UNIQUE,
	-- Facility the movement departs from.
	"origin_hub_id" BIGINT NOT NULL,
	-- Facility it arrives at. The pair plus the mode is the identity of a lane.
	"destination_hub_id" BIGINT NOT NULL,
	-- road | air | rail | sea. The mode decides the transit time and whether customs sits in the middle.
	"transport_mode" VARCHAR(16) NOT NULL DEFAULT 'road',
	-- Local departure time at the origin hub. Null for on-demand lanes that leave when full.
	"scheduled_departure" TIME,
	-- Planned door-to-door minutes for the lane. This is the number every estimate is built from.
	"transit_minutes" INTEGER NOT NULL,
	-- Days the lane runs, as digits with 1 for Monday. A weekday-only lane stored as 12345 is what makes a Friday parcel arrive on Monday.
	"operating_days" VARCHAR(7) NOT NULL DEFAULT '1234567',
	-- False retires the lane while shipments already planned on it keep their legs.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "routes" IS 'A planned movement between two facilities, not a movement that happened. Routes are the timetable of the network; whether a parcel actually made the truck is a question only the scans can answer.';
COMMENT ON COLUMN "routes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "routes"."code" IS 'Lane identifier, e.g. LON-MAN-N1. Operations plan and staff by this code.';
COMMENT ON COLUMN "routes"."origin_hub_id" IS 'Facility the movement departs from.';
COMMENT ON COLUMN "routes"."destination_hub_id" IS 'Facility it arrives at. The pair plus the mode is the identity of a lane.';
COMMENT ON COLUMN "routes"."transport_mode" IS 'road | air | rail | sea. The mode decides the transit time and whether customs sits in the middle.';
COMMENT ON COLUMN "routes"."scheduled_departure" IS 'Local departure time at the origin hub. Null for on-demand lanes that leave when full.';
COMMENT ON COLUMN "routes"."transit_minutes" IS 'Planned door-to-door minutes for the lane. This is the number every estimate is built from.';
COMMENT ON COLUMN "routes"."operating_days" IS 'Days the lane runs, as digits with 1 for Monday. A weekday-only lane stored as 12345 is what makes a Friday parcel arrive on Monday.';
COMMENT ON COLUMN "routes"."is_active" IS 'False retires the lane while shipments already planned on it keep their legs.';

CREATE INDEX "idx_routes_lane"
ON "routes" ("origin_hub_id", "destination_hub_id");

CREATE TABLE IF NOT EXISTS "shipments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The number the recipient types into a website. Unique forever, and never reused, because people bookmark it.
	"tracking_number" VARCHAR(32) NOT NULL UNIQUE,
	-- Account being billed.
	"customer_id" BIGINT NOT NULL,
	-- Product bought, which sets the promise.
	"service_level_id" BIGINT NOT NULL,
	-- First facility in the plan. Null until the shipment is inducted, because a printed label is not yet a parcel in the network.
	"origin_hub_id" BIGINT,
	-- Delivery station that will run the final mile. Recomputed if the address is corrected.
	"destination_hub_id" BIGINT,
	-- Sender as printed on the label.
	"sender_name" VARCHAR(160) NOT NULL,
	-- Collection address, snapshotted at label creation. Never a foreign key, because correcting an address book entry must not rewrite where a parcel was collected.
	"sender_address_line1" VARCHAR(200) NOT NULL,
	-- Collection city as printed.
	"sender_city" VARCHAR(120) NOT NULL,
	-- Collection postcode, which is what the sort actually keys on.
	"sender_postcode" VARCHAR(16),
	-- Collection country, snapshotted for customs.
	"sender_country_code" CHAR(2) NOT NULL,
	-- Recipient as printed on the label.
	"recipient_name" VARCHAR(160) NOT NULL,
	-- Delivery address, snapshotted. Corrections create a new value here and an exception row explaining why.
	"recipient_address_line1" VARCHAR(200) NOT NULL,
	-- Delivery city as printed.
	"recipient_city" VARCHAR(120) NOT NULL,
	-- Delivery postcode, the primary sort key through the whole network.
	"recipient_postcode" VARCHAR(16),
	-- Destination country, which decides whether customs legs exist at all.
	"recipient_country_code" CHAR(2) NOT NULL,
	-- Address for tracking notifications, separate from the account contact.
	"recipient_email" VARCHAR(320),
	-- Number the courier calls at the door.
	"recipient_phone" VARCHAR(32),
	-- Declared value in minor units, used for insurance and customs.
	"declared_value_minor" INTEGER NOT NULL DEFAULT 0,
	-- ISO 4217 currency of declared_value_minor.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Pieces in the consignment, cached so a manifest does not count packages per row.
	"package_count" SMALLINT NOT NULL DEFAULT 1,
	-- The commitment made at label creation from the service level. Frozen: it is what a refund claim is judged against.
	"promised_delivery_at" TIMESTAMPTZ,
	-- Current best estimate, recomputed from the latest scan and the remaining legs. Moves; the promise does not.
	"estimated_delivery_at" TIMESTAMPTZ,
	-- Actual delivery, copied from the delivering scan. Null until then, and the difference from the promise is the service-failure metric.
	"delivered_at" TIMESTAMPTZ,
	-- Label creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "shipments" IS 'The consignment as the shipper booked it: one sender, one recipient, one service, one tracking number. It carries no status of its own, because a three-piece shipment can be two-thirds delivered and there is no honest single word for that.';
COMMENT ON COLUMN "shipments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "shipments"."tracking_number" IS 'The number the recipient types into a website. Unique forever, and never reused, because people bookmark it.';
COMMENT ON COLUMN "shipments"."customer_id" IS 'Account being billed.';
COMMENT ON COLUMN "shipments"."service_level_id" IS 'Product bought, which sets the promise.';
COMMENT ON COLUMN "shipments"."origin_hub_id" IS 'First facility in the plan. Null until the shipment is inducted, because a printed label is not yet a parcel in the network.';
COMMENT ON COLUMN "shipments"."destination_hub_id" IS 'Delivery station that will run the final mile. Recomputed if the address is corrected.';
COMMENT ON COLUMN "shipments"."sender_name" IS 'Sender as printed on the label.';
COMMENT ON COLUMN "shipments"."sender_address_line1" IS 'Collection address, snapshotted at label creation. Never a foreign key, because correcting an address book entry must not rewrite where a parcel was collected.';
COMMENT ON COLUMN "shipments"."sender_city" IS 'Collection city as printed.';
COMMENT ON COLUMN "shipments"."sender_postcode" IS 'Collection postcode, which is what the sort actually keys on.';
COMMENT ON COLUMN "shipments"."sender_country_code" IS 'Collection country, snapshotted for customs.';
COMMENT ON COLUMN "shipments"."recipient_name" IS 'Recipient as printed on the label.';
COMMENT ON COLUMN "shipments"."recipient_address_line1" IS 'Delivery address, snapshotted. Corrections create a new value here and an exception row explaining why.';
COMMENT ON COLUMN "shipments"."recipient_city" IS 'Delivery city as printed.';
COMMENT ON COLUMN "shipments"."recipient_postcode" IS 'Delivery postcode, the primary sort key through the whole network.';
COMMENT ON COLUMN "shipments"."recipient_country_code" IS 'Destination country, which decides whether customs legs exist at all.';
COMMENT ON COLUMN "shipments"."recipient_email" IS 'Address for tracking notifications, separate from the account contact.';
COMMENT ON COLUMN "shipments"."recipient_phone" IS 'Number the courier calls at the door.';
COMMENT ON COLUMN "shipments"."declared_value_minor" IS 'Declared value in minor units, used for insurance and customs.';
COMMENT ON COLUMN "shipments"."currency_code" IS 'ISO 4217 currency of declared_value_minor.';
COMMENT ON COLUMN "shipments"."package_count" IS 'Pieces in the consignment, cached so a manifest does not count packages per row.';
COMMENT ON COLUMN "shipments"."promised_delivery_at" IS 'The commitment made at label creation from the service level. Frozen: it is what a refund claim is judged against.';
COMMENT ON COLUMN "shipments"."estimated_delivery_at" IS 'Current best estimate, recomputed from the latest scan and the remaining legs. Moves; the promise does not.';
COMMENT ON COLUMN "shipments"."delivered_at" IS 'Actual delivery, copied from the delivering scan. Null until then, and the difference from the promise is the service-failure metric.';
COMMENT ON COLUMN "shipments"."created_at" IS 'Label creation time.';

CREATE INDEX "idx_shipments_customer_created"
ON "shipments" ("customer_id", "created_at");
CREATE INDEX "idx_shipments_recipient_postcode"
ON "shipments" ("recipient_postcode");
CREATE INDEX "idx_shipments_promise"
ON "shipments" ("promised_delivery_at");

CREATE TABLE IF NOT EXISTS "packages" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Consignment the piece belongs to.
	"shipment_id" BIGINT NOT NULL,
	-- Piece barcode, which is what is physically scanned. The tracking number identifies the shipment; this identifies the box.
	"barcode" VARCHAR(40) NOT NULL UNIQUE,
	-- Position in the consignment, 1 of 3 and so on. Printed on the label so a missing piece is obvious at the door.
	"piece_sequence" SMALLINT NOT NULL DEFAULT 1,
	-- Actual weight. Grams rather than a decimal, because scale readings are integers and money is charged on them.
	"weight_grams" INTEGER NOT NULL,
	-- Longest side, used for dimensional weight and for whether it fits the conveyor.
	"length_mm" INTEGER,
	-- Second dimension.
	"width_mm" INTEGER,
	-- Third dimension.
	"height_mm" INTEGER,
	-- Description used for customs and for handling decisions.
	"contents_description" VARCHAR(200),
	-- Restricts which lanes and aircraft the piece may travel on, so it is checked at every sort.
	"is_dangerous_goods" BOOLEAN NOT NULL DEFAULT false,
	-- Cache of the latest scan: label_created | picked_up | in_transit | at_hub | out_for_delivery | delivered | exception | returned. Derived, never authored — rebuildable from scan_events at any time.
	"current_status" VARCHAR(32) NOT NULL DEFAULT 'label_created',
	-- Facility of the latest facility scan. Cache, same rule as current_status.
	"current_hub_id" BIGINT,
	-- Scan that produced the cached status. Having the pointer is what makes the cache verifiable instead of merely plausible.
	"last_scan_id" BIGINT,
	-- When the cache was last refreshed, which is not the same as when the scan happened.
	"status_updated_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "packages" IS 'The physical box, and the thing that is actually scanned. Every cached column at the bottom is a derived view of scan_events kept for query speed only: delete all four and the system still knows exactly where every parcel is.';
COMMENT ON COLUMN "packages"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "packages"."shipment_id" IS 'Consignment the piece belongs to.';
COMMENT ON COLUMN "packages"."barcode" IS 'Piece barcode, which is what is physically scanned. The tracking number identifies the shipment; this identifies the box.';
COMMENT ON COLUMN "packages"."piece_sequence" IS 'Position in the consignment, 1 of 3 and so on. Printed on the label so a missing piece is obvious at the door.';
COMMENT ON COLUMN "packages"."weight_grams" IS 'Actual weight. Grams rather than a decimal, because scale readings are integers and money is charged on them.';
COMMENT ON COLUMN "packages"."length_mm" IS 'Longest side, used for dimensional weight and for whether it fits the conveyor.';
COMMENT ON COLUMN "packages"."width_mm" IS 'Second dimension.';
COMMENT ON COLUMN "packages"."height_mm" IS 'Third dimension.';
COMMENT ON COLUMN "packages"."contents_description" IS 'Description used for customs and for handling decisions.';
COMMENT ON COLUMN "packages"."is_dangerous_goods" IS 'Restricts which lanes and aircraft the piece may travel on, so it is checked at every sort.';
COMMENT ON COLUMN "packages"."current_status" IS 'Cache of the latest scan: label_created | picked_up | in_transit | at_hub | out_for_delivery | delivered | exception | returned. Derived, never authored — rebuildable from scan_events at any time.';
COMMENT ON COLUMN "packages"."current_hub_id" IS 'Facility of the latest facility scan. Cache, same rule as current_status.';
COMMENT ON COLUMN "packages"."last_scan_id" IS 'Scan that produced the cached status. Having the pointer is what makes the cache verifiable instead of merely plausible.';
COMMENT ON COLUMN "packages"."status_updated_at" IS 'When the cache was last refreshed, which is not the same as when the scan happened.';

CREATE UNIQUE INDEX "uq_packages_shipment_sequence"
ON "packages" ("shipment_id", "piece_sequence");
CREATE INDEX "idx_packages_current_status"
ON "packages" ("current_status");
CREATE INDEX "idx_packages_hub_status"
ON "packages" ("current_hub_id", "current_status");

CREATE TABLE IF NOT EXISTS "shipment_legs" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Consignment the plan belongs to.
	"shipment_id" BIGINT NOT NULL,
	-- Order in the planned path, 1 upward.
	"leg_sequence" SMALLINT NOT NULL,
	-- Lane planned for the leg. Null for the first-mile collection and the final-mile delivery, neither of which is a scheduled lane.
	"route_id" BIGINT,
	-- Facility the leg starts at.
	"origin_hub_id" BIGINT NOT NULL,
	-- Facility it ends at.
	"destination_hub_id" BIGINT NOT NULL,
	-- When the plan says it leaves.
	"planned_departure_at" TIMESTAMPTZ NOT NULL,
	-- When the plan says it arrives. The last leg arrival is what the delivery estimate is built from.
	"planned_arrival_at" TIMESTAMPTZ NOT NULL,
	-- Filled from a departure scan. Null means it has not left, or the scan has not arrived yet.
	"actual_departure_at" TIMESTAMPTZ,
	-- Filled from an arrival scan.
	"actual_arrival_at" TIMESTAMPTZ,
	-- planned | in_progress | completed | skipped | replanned. Missing a cut-off replans the remaining legs rather than editing this one.
	"status" VARCHAR(24) NOT NULL DEFAULT 'planned',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "shipment_legs" IS 'The intended path, and the only place in this schema where the future is written down. Comparing planned against actual timestamps here is what turns a pile of scans into an on-time performance number.';
COMMENT ON COLUMN "shipment_legs"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "shipment_legs"."shipment_id" IS 'Consignment the plan belongs to.';
COMMENT ON COLUMN "shipment_legs"."leg_sequence" IS 'Order in the planned path, 1 upward.';
COMMENT ON COLUMN "shipment_legs"."route_id" IS 'Lane planned for the leg. Null for the first-mile collection and the final-mile delivery, neither of which is a scheduled lane.';
COMMENT ON COLUMN "shipment_legs"."origin_hub_id" IS 'Facility the leg starts at.';
COMMENT ON COLUMN "shipment_legs"."destination_hub_id" IS 'Facility it ends at.';
COMMENT ON COLUMN "shipment_legs"."planned_departure_at" IS 'When the plan says it leaves.';
COMMENT ON COLUMN "shipment_legs"."planned_arrival_at" IS 'When the plan says it arrives. The last leg arrival is what the delivery estimate is built from.';
COMMENT ON COLUMN "shipment_legs"."actual_departure_at" IS 'Filled from a departure scan. Null means it has not left, or the scan has not arrived yet.';
COMMENT ON COLUMN "shipment_legs"."actual_arrival_at" IS 'Filled from an arrival scan.';
COMMENT ON COLUMN "shipment_legs"."status" IS 'planned | in_progress | completed | skipped | replanned. Missing a cut-off replans the remaining legs rather than editing this one.';

CREATE UNIQUE INDEX "uq_legs_shipment_sequence"
ON "shipment_legs" ("shipment_id", "leg_sequence");
CREATE INDEX "idx_legs_route_departure"
ON "shipment_legs" ("route_id", "planned_departure_at");

CREATE TABLE IF NOT EXISTS "scan_events" (
	-- Surrogate primary key, monotonic and therefore the tie-breaker when two scans share a timestamp.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Piece scanned. Always a piece, never a shipment: the barcode under the scanner belongs to a box.
	"package_id" BIGINT NOT NULL,
	-- Consignment, copied from the package so shipment-wide tracking is one index scan rather than a join.
	"shipment_id" BIGINT NOT NULL,
	-- Facility the scan happened at. Null for a roadside scan by a courier, which has coordinates instead.
	"hub_id" BIGINT,
	-- Person who scanned it, when it was a handheld rather than a conveyor.
	"courier_id" BIGINT,
	-- label_created | picked_up | arrived_at_hub | departed_hub | customs_hold | customs_cleared | out_for_delivery | delivery_attempted | delivered | held_at_facility | returned_to_sender | damaged | lost.
	"event_code" VARCHAR(32) NOT NULL,
	-- When the scan physically happened, from the device. This is the field the timeline is ordered by.
	"occurred_at" TIMESTAMPTZ NOT NULL,
	-- When the server received it. Handhelds work offline in vans and basements, so scans routinely land hours late and out of order.
	"recorded_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- handheld | conveyor | api | manual | partner. Partner scans come from another carrier and are the least trustworthy.
	"source" VARCHAR(16) NOT NULL DEFAULT 'handheld',
	-- Position at the scan, present for roadside and doorstep events.
	"latitude" NUMERIC(9,6),
	-- Position at the scan.
	"longitude" NUMERIC(9,6),
	-- Free text from the scanner, e.g. left with neighbour at number 14.
	"notes" VARCHAR(300),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "scan_events" IS 'The truth, and the only table here that is genuinely append-only. Nothing updates or deletes a scan. Every status, every estimate and every performance number in this schema is a function of these rows, which is why a scan arriving four hours late fixes itself instead of corrupting anything.';
COMMENT ON COLUMN "scan_events"."id" IS 'Surrogate primary key, monotonic and therefore the tie-breaker when two scans share a timestamp.';
COMMENT ON COLUMN "scan_events"."package_id" IS 'Piece scanned. Always a piece, never a shipment: the barcode under the scanner belongs to a box.';
COMMENT ON COLUMN "scan_events"."shipment_id" IS 'Consignment, copied from the package so shipment-wide tracking is one index scan rather than a join.';
COMMENT ON COLUMN "scan_events"."hub_id" IS 'Facility the scan happened at. Null for a roadside scan by a courier, which has coordinates instead.';
COMMENT ON COLUMN "scan_events"."courier_id" IS 'Person who scanned it, when it was a handheld rather than a conveyor.';
COMMENT ON COLUMN "scan_events"."event_code" IS 'label_created | picked_up | arrived_at_hub | departed_hub | customs_hold | customs_cleared | out_for_delivery | delivery_attempted | delivered | held_at_facility | returned_to_sender | damaged | lost.';
COMMENT ON COLUMN "scan_events"."occurred_at" IS 'When the scan physically happened, from the device. This is the field the timeline is ordered by.';
COMMENT ON COLUMN "scan_events"."recorded_at" IS 'When the server received it. Handhelds work offline in vans and basements, so scans routinely land hours late and out of order.';
COMMENT ON COLUMN "scan_events"."source" IS 'handheld | conveyor | api | manual | partner. Partner scans come from another carrier and are the least trustworthy.';
COMMENT ON COLUMN "scan_events"."latitude" IS 'Position at the scan, present for roadside and doorstep events.';
COMMENT ON COLUMN "scan_events"."longitude" IS 'Position at the scan.';
COMMENT ON COLUMN "scan_events"."notes" IS 'Free text from the scanner, e.g. left with neighbour at number 14.';

CREATE INDEX "idx_scans_package_time"
ON "scan_events" ("package_id", "occurred_at");
CREATE INDEX "idx_scans_shipment_time"
ON "scan_events" ("shipment_id", "occurred_at");
CREATE INDEX "idx_scans_hub_time"
ON "scan_events" ("hub_id", "occurred_at");
CREATE INDEX "idx_scans_code_time"
ON "scan_events" ("event_code", "occurred_at");

CREATE TABLE IF NOT EXISTS "couriers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Staff or contractor identifier, printed on the proof of delivery.
	"employee_code" VARCHAR(24) NOT NULL UNIQUE,
	-- Name shown to the recipient in tracking.
	"full_name" VARCHAR(160) NOT NULL,
	-- Delivery station the courier reports to, which scopes the rounds they can be assigned.
	"home_hub_id" BIGINT NOT NULL,
	-- Contact number, sometimes surfaced to the recipient on the day of delivery.
	"phone" VARCHAR(32),
	-- van | truck | bike | walker. Decides which packages can be loaded at all.
	"vehicle_type" VARCHAR(24),
	-- False retires the account without detaching the scans and deliveries they made.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "couriers" IS 'The person at the door. Kept as a table rather than a name on a scan because a delivery dispute needs to reach a specific human, and because rounds are assigned per courier.';
COMMENT ON COLUMN "couriers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "couriers"."employee_code" IS 'Staff or contractor identifier, printed on the proof of delivery.';
COMMENT ON COLUMN "couriers"."full_name" IS 'Name shown to the recipient in tracking.';
COMMENT ON COLUMN "couriers"."home_hub_id" IS 'Delivery station the courier reports to, which scopes the rounds they can be assigned.';
COMMENT ON COLUMN "couriers"."phone" IS 'Contact number, sometimes surfaced to the recipient on the day of delivery.';
COMMENT ON COLUMN "couriers"."vehicle_type" IS 'van | truck | bike | walker. Decides which packages can be loaded at all.';
COMMENT ON COLUMN "couriers"."is_active" IS 'False retires the account without detaching the scans and deliveries they made.';

CREATE INDEX "idx_couriers_hub_active"
ON "couriers" ("home_hub_id", "is_active");

CREATE TABLE IF NOT EXISTS "delivery_attempts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Piece being delivered.
	"package_id" BIGINT NOT NULL,
	-- Courier who tried.
	"courier_id" BIGINT NOT NULL,
	-- Scan that recorded the attempt. The scan is the fact; this row is the structured detail around it.
	"scan_event_id" BIGINT,
	-- Which try this was. Most carriers stop after three, and that rule is unimplementable without this column.
	"attempt_number" SMALLINT NOT NULL DEFAULT 1,
	-- When the courier was at the door.
	"attempted_at" TIMESTAMPTZ NOT NULL,
	-- delivered | no_answer | refused | access_denied | address_not_found | unsafe_to_leave | rescheduled_by_recipient | closed.
	"outcome" VARCHAR(32) NOT NULL,
	-- Where the attempt happened, which occasionally proves the courier was never at the address.
	"latitude" NUMERIC(9,6),
	-- Where the attempt happened.
	"longitude" NUMERIC(9,6),
	-- Whether a card was left, which decides what the recipient is told to do next.
	"note_left" BOOLEAN NOT NULL DEFAULT false,
	-- Planned retry date. Null when there will be no retry, which is itself a decision worth recording.
	"next_attempt_on" DATE,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "delivery_attempts" IS 'One row per knock. A counter on the package would answer how many times but never why, and the why is what decides whether the next move is a retry, a locker, or a return to sender.';
COMMENT ON COLUMN "delivery_attempts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "delivery_attempts"."package_id" IS 'Piece being delivered.';
COMMENT ON COLUMN "delivery_attempts"."courier_id" IS 'Courier who tried.';
COMMENT ON COLUMN "delivery_attempts"."scan_event_id" IS 'Scan that recorded the attempt. The scan is the fact; this row is the structured detail around it.';
COMMENT ON COLUMN "delivery_attempts"."attempt_number" IS 'Which try this was. Most carriers stop after three, and that rule is unimplementable without this column.';
COMMENT ON COLUMN "delivery_attempts"."attempted_at" IS 'When the courier was at the door.';
COMMENT ON COLUMN "delivery_attempts"."outcome" IS 'delivered | no_answer | refused | access_denied | address_not_found | unsafe_to_leave | rescheduled_by_recipient | closed.';
COMMENT ON COLUMN "delivery_attempts"."latitude" IS 'Where the attempt happened, which occasionally proves the courier was never at the address.';
COMMENT ON COLUMN "delivery_attempts"."longitude" IS 'Where the attempt happened.';
COMMENT ON COLUMN "delivery_attempts"."note_left" IS 'Whether a card was left, which decides what the recipient is told to do next.';
COMMENT ON COLUMN "delivery_attempts"."next_attempt_on" IS 'Planned retry date. Null when there will be no retry, which is itself a decision worth recording.';

CREATE UNIQUE INDEX "uq_attempts_package_number"
ON "delivery_attempts" ("package_id", "attempt_number");
CREATE INDEX "idx_attempts_courier_time"
ON "delivery_attempts" ("courier_id", "attempted_at");

CREATE TABLE IF NOT EXISTS "exceptions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Piece affected.
	"package_id" BIGINT NOT NULL,
	-- Scan that raised it, when it came from the network rather than from a support agent.
	"scan_event_id" BIGINT,
	-- damaged | lost | customs_hold | weather_delay | address_invalid | refused | missorted | oversized | held_for_pickup.
	"kind" VARCHAR(32) NOT NULL,
	-- info | warning | critical. Critical stops the parcel moving and pages an operations team.
	"severity" VARCHAR(16) NOT NULL DEFAULT 'warning',
	-- When the problem was raised.
	"opened_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Person or system that raised it. Null for automatic detection.
	"opened_by" VARCHAR(120),
	-- What actually happened, in words a support agent can read to a customer.
	"detail" VARCHAR(400),
	-- Resolution time. Null while open, which makes the open-exception queue a single index scan.
	"resolved_at" TIMESTAMPTZ,
	-- redelivered | returned | claim_paid | address_corrected | released | written_off.
	"resolution" VARCHAR(32),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "exceptions" IS 'The parcel is stuck and somebody has to act. Exceptions are separate from scans because a scan is an observation that can never change, while an exception is a case with a lifecycle, an owner and a resolution.';
COMMENT ON COLUMN "exceptions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "exceptions"."package_id" IS 'Piece affected.';
COMMENT ON COLUMN "exceptions"."scan_event_id" IS 'Scan that raised it, when it came from the network rather than from a support agent.';
COMMENT ON COLUMN "exceptions"."kind" IS 'damaged | lost | customs_hold | weather_delay | address_invalid | refused | missorted | oversized | held_for_pickup.';
COMMENT ON COLUMN "exceptions"."severity" IS 'info | warning | critical. Critical stops the parcel moving and pages an operations team.';
COMMENT ON COLUMN "exceptions"."opened_at" IS 'When the problem was raised.';
COMMENT ON COLUMN "exceptions"."opened_by" IS 'Person or system that raised it. Null for automatic detection.';
COMMENT ON COLUMN "exceptions"."detail" IS 'What actually happened, in words a support agent can read to a customer.';
COMMENT ON COLUMN "exceptions"."resolved_at" IS 'Resolution time. Null while open, which makes the open-exception queue a single index scan.';
COMMENT ON COLUMN "exceptions"."resolution" IS 'redelivered | returned | claim_paid | address_corrected | released | written_off.';

CREATE INDEX "idx_exceptions_package_time"
ON "exceptions" ("package_id", "opened_at");
CREATE INDEX "idx_exceptions_open_queue"
ON "exceptions" ("kind", "resolved_at");

CREATE TABLE IF NOT EXISTS "proofs_of_delivery" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Piece delivered. Unique, because a package is delivered exactly once and a second proof means something went badly wrong.
	"package_id" BIGINT NOT NULL UNIQUE,
	-- The successful attempt. Unique so one attempt cannot produce two proofs.
	"delivery_attempt_id" BIGINT UNIQUE,
	-- Courier who completed the delivery.
	"courier_id" BIGINT NOT NULL,
	-- Handover time, taken from the device rather than the server.
	"delivered_at" TIMESTAMPTZ NOT NULL,
	-- Name given at the door. Null for a contactless or safe-place delivery, which is exactly the case that later gets disputed.
	"received_by_name" VARCHAR(160),
	-- recipient | household | neighbour | reception | safe_place | locker. It decides whether the parcel reached the addressee or merely the address.
	"relationship" VARCHAR(24) NOT NULL DEFAULT 'recipient',
	-- Object storage key for the signature capture. The image never lives in the database, only the pointer.
	"signature_image_key" VARCHAR(300),
	-- Object storage key for the doorstep photo, which has quietly replaced the signature for most consumer deliveries.
	"photo_image_key" VARCHAR(300),
	-- Coordinates at handover, the strongest single piece of evidence in a not-received claim.
	"latitude" NUMERIC(9,6),
	-- Coordinates at handover.
	"longitude" NUMERIC(9,6),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "proofs_of_delivery" IS 'The evidence that the job was done, one row per package at most. It is deliberately separate from the delivering scan: the scan says delivered, this says to whom, where, and with what proof, and those are the facts a claim actually turns on.';
COMMENT ON COLUMN "proofs_of_delivery"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "proofs_of_delivery"."package_id" IS 'Piece delivered. Unique, because a package is delivered exactly once and a second proof means something went badly wrong.';
COMMENT ON COLUMN "proofs_of_delivery"."delivery_attempt_id" IS 'The successful attempt. Unique so one attempt cannot produce two proofs.';
COMMENT ON COLUMN "proofs_of_delivery"."courier_id" IS 'Courier who completed the delivery.';
COMMENT ON COLUMN "proofs_of_delivery"."delivered_at" IS 'Handover time, taken from the device rather than the server.';
COMMENT ON COLUMN "proofs_of_delivery"."received_by_name" IS 'Name given at the door. Null for a contactless or safe-place delivery, which is exactly the case that later gets disputed.';
COMMENT ON COLUMN "proofs_of_delivery"."relationship" IS 'recipient | household | neighbour | reception | safe_place | locker. It decides whether the parcel reached the addressee or merely the address.';
COMMENT ON COLUMN "proofs_of_delivery"."signature_image_key" IS 'Object storage key for the signature capture. The image never lives in the database, only the pointer.';
COMMENT ON COLUMN "proofs_of_delivery"."photo_image_key" IS 'Object storage key for the doorstep photo, which has quietly replaced the signature for most consumer deliveries.';
COMMENT ON COLUMN "proofs_of_delivery"."latitude" IS 'Coordinates at handover, the strongest single piece of evidence in a not-received claim.';
COMMENT ON COLUMN "proofs_of_delivery"."longitude" IS 'Coordinates at handover.';

CREATE INDEX "idx_pod_courier_time"
ON "proofs_of_delivery" ("courier_id", "delivered_at");

